INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein PPS-System immer für die Fertigung notwendig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Dienstleistungen einsetzbar"}, {"text": "Ja", "correct": false, "because": "Nicht nur Fertigung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel eines solchen Systems?', 3, '[{"text": "Effiziente Ressourcennutzung", "correct": true, "because": "Optimiert Produktionsprozesse"}, {"text": "Maximale Lagerbestände", "correct": false, "because": "Gegenteil des Ziels"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Automatisierung bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen umfasst ein PPS-System typischerweise?', 5, '[{"text": "Produktionsplanung", "correct": true, "because": "Legt Fertigungsabläufe fest"}, {"text": "Kapazitätssteuerung", "correct": true, "because": "Verwaltet Ressourcen"}, {"text": "Bildbearbeitung", "correct": false, "because": "Nicht relevant"}, {"text": "Social-Media-Analyse", "correct": false, "because": "Andere Domäne"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PPS-Systeme steuern Materialflüsse. b) Sie ersetzen die Produktion.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) unterstützt, ersetzt nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Implementierung eines PPS-Systems?', 4, '[{"text": "Datenintegration", "correct": false, "because": "Verknüpft Prozesse"}, {"text": "Anwenderschulung", "correct": false, "because": "Sichert Nutzung"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein PPS-System immer cloudbasiert ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokal installierbar"}, {"text": "Ja", "correct": false, "because": "Cloud optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für ein PPS-System entscheidend?', 3, '[{"text": "Echtzeitdaten", "correct": true, "because": "Ermöglicht präzise Steuerung"}, {"text": "Hohe Grafikleistung", "correct": false, "because": "Sekundär"}, {"text": "Manuelle Eingaben", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein PPS-System?', 5, '[{"text": "Kostensenkung", "correct": true, "because": "Optimiert Ressourcen"}, {"text": "Transparenz", "correct": true, "because": "Zeigt Abläufe"}, {"text": "Einmalige Nutzung", "correct": false, "because": "Kontinuierlich eingesetzt"}, {"text": "Grafische Animationen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) PPS-Systeme planen Fertigungsabläufe. b) Sie sind nur für Großunternehmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch für KMUs geeignet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein PPS-System?', 4, '[{"text": "Datenintegration", "correct": false, "because": "Verknüpft Systeme"}, {"text": "Planungslogik", "correct": false, "because": "Kern der Steuerung"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für PPS"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein PPS-System nur für die Planung zuständig?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst auch Steuerung"}, {"text": "Ja", "correct": false, "because": "Planung und Steuerung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Module sind typisch für ein PPS-System?', 4, '[{"text": "Materialwirtschaft", "correct": true, "because": "Verwaltet Bestände"}, {"text": "Fertigungssteuerung", "correct": true, "because": "Koordiniert Abläufe"}, {"text": "Videobearbeitung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass PPS-Systeme immer teuer sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten variieren je nach Größe"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig teuer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Einführung eines PPS-Systems?', 3, '[{"text": "Anwenderakzeptanz", "correct": true, "because": "Sichert effektive Nutzung"}, {"text": "Maximale Komplexität", "correct": false, "because": "Erschwert Nutzung"}, {"text": "Manuelle Eingaben", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PPS-Systeme reduzieren Durchlaufzeiten. b) Sie ersetzen Mitarbeiter.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) unterstützt, ersetzt nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei PPS-Systemen?', 5, '[{"text": "Datenqualität", "correct": true, "because": "Fehler beeinträchtigen Planung"}, {"text": "Integrationsaufwand", "correct": true, "because": "Systeme müssen vernetzt sein"}, {"text": "Hohe Grafikleistung", "correct": false, "because": "Nicht primär"}, {"text": "Einmalige Einführung", "correct": false, "because": "Langfristige Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem PPS-System unwichtig?', 3, '[{"text": "Ressourcenplanung", "correct": false, "because": "Kernfunktion"}, {"text": "Liefertermine", "correct": false, "because": "Wichtig für Produktion"}, {"text": "Bildschirmauflösung", "correct": true, "because": "Kein PPS-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein PPS-System für Einzelfertigung geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibel anpassbar"}, {"text": "Nein", "correct": false, "because": "Auch für Einzelfertigung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt ein PPS-System die Lagerverwaltung?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzt, aber ersetzt nicht"}, {"text": "Ja", "correct": false, "because": "Teilfunktion, nicht vollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem PPS-System?', 4, '[{"text": "Planung einer Fertigungslinie", "correct": true, "because": "Koordiniert Abläufe"}, {"text": "Erstellung eines Logos", "correct": false, "because": "Kreative Aufgabe"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Technische Aufgabe"}]');
